  ui_story_30090401_117_dialog_content = "Sim, demorou um pouco.",
  ui_story_30090401_118_dialog_content = "Tive que tratar meus adoráveis crentes com a máxima sinceridade.",
  ui_story_30090401_X118_dialog_content = "Embora eu tenha usado uma caixa falsa, ninguém sabia.",
  ui_story_30090401_119_dialog_content = "Tirei as bugigangas da caixa e as distribuí. Todos os crentes choraram lágrimas de alegria.",
  ui_story_30090401_120_dialog_content = "Eu consegui fazer isso tudo graças a você por cuidar da Wispy para mim.",
  ui_story_30090401_121_dialog_content = "Obrigado, mas ainda me sinto mal por fazer a Wispy chorar.",
  ui_story_30090401_122_dialog_content = "Não, aquelas não eram lágrimas.",
  ui_story_30090401_123_dialog_content = "<color=#FFB400>Memórias tristes são a comida favorita da Wispy</color>. Ela estava apenas com fome.",
  ui_story_30090401_124_dialog_content = "Então... Ele viu minha tristeza e desespero e babou?",
  ui_story_30090401_125_dialog_content = "Infelizmente, temo que sim.",
  ui_story_30090401_126_dialog_content = "*Move as mechas felizmente*",
  ui_story_30090401_127_dialog_content = "Entendi.",
  ui_story_30090401_128_dialog_content = "<size=45>Ehh—</size>",
  ui_story_30090401_129_dialog_content = "<color=#e8d9bb>Wispy é como um gato, tem personalidade. Seja gentil com ele.</color>",
  ui_story_30090601_1_dialog_content = "Mercado de Twin Pavilions Bay... Este lugar parece estar sempre cheio de movimento, dia e noite.",
  ui_story_30090601_2_dialog_content = "Huh? Aquela pessoa à frente parece com...",
  ui_story_30090601_3_dialog_content = "Não é todo dia que temos um jovem tão bonito olhando nossos produtos. Sabe de uma coisa, vou te dar um desconto de vinte por cento em qualquer um desses livros que te agradar.",
  ui_story_30090601_4_dialog_content = "Obrigado pelo gentil gesto, senhora.",
  ui_story_30090601_5_dialog_content = "Se esses livros antigos ajudarem a esclarecer a verdade, serei eternamente grato pela sua bondade.",
  ui_story_30090601_6_dialog_content = "Você é educado, não é! Heheh... Faz tempo que ninguém me chama de \"senhora.\"",
  ui_story_30090601_7_dialog_content = "Aliás, tenho alguns livros antigos incompletos na minha loja. Estaria interessado em dar uma olhada, jovem?",
  ui_story_30090601_8_dialog_content = "Claro, adoraria dar uma olhada, se você estiver de acordo.",
  ui_story_30090601_9_dialog_content = "No começo, eu não tinha certeza por causa daquela roupa, mas aquele comportamento e aquela maneira de falar...",
  ui_story_30090601_10_dialog_content = "Faust, é realmente você.",
  ui_story_30090601_11_dialog_content = "PlayerName? Não pensei que te encontraria aqui. Que surpresa agradável.",
  ui_story_30090601_12_dialog_content = "O que você está fazendo aqui? E o que é com todos os livros?",
  ui_story_30090601_13_dialog_content = "Tenho estudado a cultura antiga de Longzhou recentemente.",
  ui_story_30090601_14_dialog_content = "E eu descobri que a melhor maneira de estudar uma cultura é se imergir nela.",
  ui_story_30090601_15_dialog_content = "Para entender completamente o significado da roupa, comida e maneirismos de uma cultura, é preciso vivenciá-los pessoalmente.",
  ui_story_30090601_16_dialog_content = "Então, recentemente, tenho ficado aqui em Twin Pavilions Bay, reunindo vários livros antigos e relíquias culturais de Longzhou.",
  ui_story_30090601_17_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_30090601_18_dialog_content = "Aqui—estes são todos os nossos antigos textos misturados.",
  ui_story_30090601_19_dialog_content = "De qualquer forma, ninguém quis tirá-los das minhas mãos depois de todo esse tempo, então se você quiser, pode levar todos, sem nenhum custo.",
  ui_story_30090601_20_dialog_content = "<size=45>Existem muitos deles!</size>",
  ui_story_30090601_21_dialog_content = "Mas eles realmente estão todos em pedaços. Nem uma única página desses livros está intacta. Você ainda consegue lê-los...?",
  ui_story_30090601_22_dialog_content = "Jamais esquecerei sua generosidade, senhora.",
  ui_story_30090601_23_dialog_content = "Agora, por favor, permita-me colocar esses livros antigos na minha mala.",
  ui_story_30090601_24_dialog_content = "Espere! Não faça algo tão perigoso na frente de todas essas pessoas.",
  ui_story_30090601_25_dialog_content = "Onde você está hospedado agora? Deixe-me ajudar a carregá-los.",
  ui_story_30090601_26_dialog_content = "Certamente. Muito obrigado.",
  ui_story_30090601_27_dialog_content = "Uau... Você tem livros e todo tipo de coisa espalhados por todo lugar aqui. Você realmente não brinca em serviço quando se trata de estudar, hein?",
  ui_story_30090601_28_dialog_content = "Bem, Longzhou tem uma história muito longa e é um vasto território rico em recursos.",
  ui_story_30090601_29_dialog_content = "Explorar as origens de tais questões não é algo que se possa realizar da noite para o dia.",
  ui_story_30090601_30_dialog_content = "O antigo roteiro de Longzhou é um assunto que requer um estudo minucioso por si só.",
  ui_story_30090601_31_dialog_content = "A formação de caracteres envolve pictografia, ideogramas, associação, pictofonético...",
  ui_story_30090601_32_dialog_content = "Palavras que uma vez expressaram um certo significado podem ter evoluído para uma forma completamente diferente em textos escritos dez ou cem anos depois.",
  ui_story_30090601_33_dialog_content = "Pegue, por exemplo, esses textos antigos básicos que li recentemente.",
  ui_story_30090601_34_dialog_content = "Este personagem aqui originalmente tinha vários significados.",
  ui_story_30090601_35_dialog_content = "Mas em textos posteriores, foi modificado com diferentes radicais.",
  ui_story_30090601_36_dialog_content = "Ao adicionar esses componentes radicais, o caráter original desenvolveu uma série de novos significados...",
  ui_story_30090601_37_dialog_content = "Radicais?",
  ui_story_30090601_38_dialog_content = "Deixe-me escrever alguns para você ver.",
  ui_story_30090601_39_dialog_content = "(Ele até preparou todos os pincéis de caligrafia e papel especial. Acho que ele estava falando sério quando disse que estava se imergindo na cultura.)",
  ui_story_30090601_40_dialog_content = "(E... ele é realmente muito bom nisso!)",
  ui_story_30090601_41_dialog_content = "Assim como isso, você pode se ramificar em múltiplos significados que originalmente eram representados por um único caractere.",
  ui_story_30090601_42_dialog_content = "Embora este sistema seja muito intrincado, também pode facilmente levar à confusão.",
  ui_story_30090601_43_dialog_content = "Esse caractere aqui significa \"abrir\"... ou significa \"estabelecer\"?",
  ui_story_30090601_44_dialog_content = "Hmm? Você já estudou isso antes?",
  ui_story_30090601_45_dialog_content = "Não, é só que ouvi dizer que a maioria das coisas em Longzhou estão de alguma forma relacionadas aos sentidos.",
  ui_story_30090601_46_dialog_content = "Então, esse caractere é colocado dentro do radical que representa uma porta, então eu acho que o significado deve ser algo semelhante a abrir uma porta... Certo?",
  ui_story_30090601_47_dialog_content = "E este contém aquela pequena parte que indica movimento... então, poderia estar relacionado à ideia de... \"evasão\"?",
  ui_story_30090601_48_dialog_content = "Isso está precisamente correto.",
  ui_story_30090601_49_dialog_content = "Devo dizer, você demonstra um nível excepcional de talento natural para isso!",
  ui_story_30090601_50_dialog_content = "Vamos lá, eu não sei muito sobre esses personagens.",
  ui_story_30090601_51_dialog_content = "Provavelmente é apenas porque fiz muitos amigos em Longzhou recentemente e peguei algumas coisas interessantes deles sem perceber.",
  ui_story_30090601_52_dialog_content = "Esse é apenas um dos seus muitos superpoderes.",
  ui_story_30090601_53_dialog_content = "Eu me pergunto, será que eu poderia possivelmente usar suas conexões sociais em algum momento no futuro para realizar algum trabalho de campo em Longzhou?",
  ui_story_30090601_54_dialog_content = "Talvez também existam pessoas naquele grande continente interessadas em aprender sobre nossa riqueza de conhecimento e muitas verdades.",
  ui_story_30090601_55_dialog_content = "... Eu sabia.",
  ui_story_30090601_56_dialog_content = "Acho que eles podem ver isso simplesmente como compartilhamento de informações e promoção da comunicação entre nossos dois continentes... Deve estar tudo bem.",
  ui_story_30090601_57_dialog_content = "Então, permita-me agradecer antecipadamente pela sua gentileza.",
  ui_story_30090601_58_dialog_content = "E como um sinal de gratidão...",
  ui_story_30090601_59_dialog_content = "Você já desenvolveu algum interesse na antiga caligrafia de Longzhou, não é?",
  ui_story_30090601_60_dialog_content = "Gostaria que eu te ensinasse a escrever esses caracteres?",
  ui_story_30090601_61_dialog_content = "<size=45>Hã? Sério?</size>Mas todos esses personagens parecem tão complicados...",
  ui_story_30090601_62_dialog_content = "Somente através da ação podemos empurrar a porta da verdade.",
  ui_story_30090601_63_dialog_content = "Por favor—sente-se.",
  ui_story_30090601_64_dialog_content = "Eu sou totalmente a favor de tomar uma atitude, mas como eu deveria usar esse pincel? A ponta é tão macia, mal consigo controlá-la...",
  ui_story_30090601_65_dialog_content = "Ah! Eu borrei tinta por todo o lugar!",
  ui_story_30090601_66_dialog_content = "Não entre em pânico.",
  ui_story_30090601_67_dialog_content = "Tal escrita não deve ser apressada ou executada descuidadamente, e não deve haver um traço de incerteza em seu coração.",
  ui_story_30090601_68_dialog_content = "Seu pincel deve pontilhar o papel como uma pedra caindo resolutamente de um pico de montanha, estender-se horizontalmente, como nuvens se estendendo por mil milhas, e deslizar verticalmente, como uma videira eterna, escalando por toda a eternidade...",
  ui_story_30090601_69_dialog_content = "Siga o impulso do pincel e você verá que os caracteres se formam naturalmente.",
  ui_story_30090601_70_dialog_content = "Marque o papel, como uma pedra caindo do pico de uma montanha.",
