  ui_story_30090601_72_dialog_content = "Deslize verticalmente, como uma videira subindo pela eternidade...",
  ui_story_30090601_73_dialog_content = "Acho que estou pegando o jeito! Produzir belos traços realmente não é tão difícil quanto parece.",
