  ui_story_30090601_75_dialog_content = "É como se esses traços que pintei agora nem sequer formassem uma única palavra.",
  ui_story_30090601_76_dialog_content = "Hum...",
  ui_story_30090601_77_dialog_content = "No que você acredita que as \"palavras\" sejam, em essência?",
  ui_story_30090601_78_option_content = "Acho que nunca realmente pensei nisso antes.",
