  ui_story_30090601_81_dialog_content = "Boa resposta.",
  ui_story_30090601_82_dialog_content = "Embora estejamos bastante acostumados a nos encontrar constantemente cercados por palavras.",
  ui_story_30090601_83_dialog_content = "Em meus olhos, a mera existência deles é um precioso milagre a ser admirado diariamente.",
