  ui_story_30090601_85_dialog_content = "Agora, vou te contar por que eu os comprei.",
  ui_story_30090601_86_dialog_content = "É porque as palavras são faíscas da verdade.",
  ui_story_30090601_87_dialog_content = "Através das palavras, o conhecimento daqueles que vieram antes de nós pode ser preservado e acumulado.",
  ui_story_30090601_88_dialog_content = "Transcendendo as marés do tempo, eles se tornam um poema que pode ser recitado mil anos depois.",
  ui_story_30090601_89_dialog_content = "Embora sejam fragmentos, assim como o fogo nasce de simples cinzas—",
  ui_story_30090601_90_dialog_content = "Essas faíscas espalhadas possuem a capacidade de provocar uma tempestade furiosa com apenas um pouco de ajuda.",
  ui_story_30090601_91_dialog_content = "Cada frase, cada palavra, cada caractere do passado pode potencialmente ser um sinal deixado por nossos antecessores em sua jornada em busca da verdade.",
  ui_story_30090601_92_dialog_content = "Claro que um legado como esse vale a pena preservar e explorar.",
  ui_story_30090601_93_dialog_content = "Claro que não!",
  ui_story_30090601_94_dialog_content = "Então, quando você escrever esses caracteres, não foque muito nas suas pinceladas.",
  ui_story_30090601_95_dialog_content = "Pergunte a si mesmo por que esse personagem possui tal forma e qual significado isso poderia ter.",
