  ui_story_30090601_100_dialog_content = "O próprio ponto de sua existência é transmitir mais do que pode ser visto apenas com o olho.",
  ui_story_30090601_101_dialog_content = "Agora que você também entende essa verdade profunda, acredito que conseguirá escrever com mais confiança.",
  ui_story_30090601_102_dialog_content = "Sim! Obrigado, Faust.",
